PRAGMA foreign_keys = ON;

-- Security and legal holds intentionally cannot be outsourced, but they still require a complete
-- numbered path so an authorized operator is never left with a dead-end alert.
DELETE FROM resolution_steps WHERE playbook_code IN ('SECURITY_HOLD','LEGAL_HOLD');

INSERT INTO resolution_steps
(playbook_code,sequence,actor_type,title,instruction,link_kind,explicit_url,automatic_verification_note) VALUES
('SECURITY_HOLD',1,'SYSTEM','Contain the affected scope','Keep the affected merchant, transaction, credential, integration, or runtime capability in its fail-closed state. Preserve alert evidence, processor references, audit events, and timestamps. Do not rotate or disclose unrelated secrets and do not clear the hold merely to restore service.','NONE',NULL,'Containment remains active until the authorized security condition is cleared.'),
('SECURITY_HOLD',2,'SYSTEM','Identify the authoritative security source','Determine whether the condition is a Builtegrity credential/configuration problem or an external provider security event. Use only the affected provider dashboard/support channel and the Builtegrity incident evidence; never send passwords, API keys, card data, bank credentials, SSNs, or identity documents through ordinary support messages.','NONE',NULL,'The incident record must identify the actual affected provider/system before corrective action.'),
('SECURITY_HOLD',3,'SYSTEM','Perform the minimum authorized correction','Use the authorized security path to revoke or rotate only the affected credential, disable the compromised capability, correct the verified configuration defect, or complete the provider-requested security action. Generic workforce vendors cannot authorize or perform security clearance.','NONE',NULL,'Every privileged change must remain auditable and scoped to the verified condition.'),
('SECURITY_HOLD',4,'SYSTEM','Verify before clearing the hold','Rerun the originating security/watchdog checks and confirm the affected integration or capability is healthy with the replacement credential/configuration. Clear the hold only through AUTHORIZED_SECURITY_CLEARANCE after the machine-observable condition is clean.','NONE',NULL,'A human completion claim alone cannot close a security hold.'),

('LEGAL_HOLD',1,'SYSTEM','Preserve the blocked legal state','Keep onboarding, checkout, jurisdiction, document, or other legally gated activity blocked exactly where the legal control stopped it. Preserve the merchant/customer jurisdiction snapshot, accepted document versions, counsel references, and the originating compliance evidence.','NONE',NULL,'No payment or onboarding bypass is permitted while the legal hold remains open.'),
('LEGAL_HOLD',2,'SYSTEM','Identify the exact legal gate','Map the hold to the specific missing or expired legal/compliance requirement: jurisdiction clearance, approved document version, merchant acceptance, PCI evidence, tax treatment, sanctions/restricted-business evidence, or another named compliance obligation. Do not substitute a generic approval.','NONE',NULL,'The case must name the precise gate and evidence needed to satisfy it.'),
('LEGAL_HOLD',3,'SYSTEM','Obtain only authorized legal/compliance evidence','Route the requirement to the authorized legal/compliance decision path or the named external authority/provider when applicable. Record counsel/reference evidence and effective dates in the existing compliance tables. Generic workforce vendors cannot interpret law or authorize legal clearance.','NONE',NULL,'Legal evidence must be versioned and attributable before the gate can change state.'),
('LEGAL_HOLD',4,'SYSTEM','Machine-check the gate again','Rerun the exact compliance readiness view/watchdog after the required evidence is recorded. Clear the hold only through AUTHORIZED_LEGAL_CLEARANCE when every required underlying gate evaluates ready.','NONE',NULL,'The system—not a free-text note—determines whether the legal gate is actually satisfied.');
